#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    long long n, k;
    std::cin >> n >> k;

    std::vector<long long> divisors, largeDivisors;

    for (long long i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            divisors.push_back(i);
            if (i != n / i)
                largeDivisors.push_back(n / i);
        }
    }

    divisors.insert(divisors.end(), largeDivisors.rbegin(), largeDivisors.rend());

    if (k < 1 || k > static_cast<long long>(divisors.size()))
        std::cout << -1;
    else
        std::cout << divisors[k - 1];

    return 0;
}

