int main() {
    long long n, k;
    std::cin >> n >> k;

    std::vector<long long> divisors;
    long long i = 1;

    for (; i <= n / i; ++i) {
        if (n % i == 0)
            divisors.push_back(i);
    }

    while (--i > 0) {
        if (n % i == 0 && i != n / i)
            divisors.push_back(n / i);
    }

    if (k < 1 || k > static_cast<long long>(divisors.size()))
        std::cout << -1;
    else
        std::cout << divisors[k - 1];

    return 0;
}

